// Node-RED Function: put this after the HTTP Request node.
// It parses the Liyang power API response and writes values in the same
// naming format used by the reused Jiyuan Node-RED logic.

const ZERO_MISSING = true;

function parsePayload(payload) {
    if (typeof payload === "string") {
        try {
            return JSON.parse(payload);
        } catch (err) {
            node.error("功率API返回不是合法JSON: " + err.message, msg);
            return null;
        }
    }
    return payload;
}

function hasOwn(obj, key) {
    return Object.prototype.hasOwnProperty.call(obj, key);
}

function asNumber(value) {
    const numberValue = Number(value);
    return Number.isFinite(numberValue) ? numberValue : null;
}

function setPoint(target, name, value) {
    const numberValue = asNumber(value);
    target[name] = numberValue === null ? 0 : numberValue;
}

function setDirect(target, valueByDeviceId, missingDeviceIds, deviceId, name) {
    if (hasOwn(valueByDeviceId, deviceId)) {
        setPoint(target, name, valueByDeviceId[deviceId]);
        return;
    }
    missingDeviceIds.push(deviceId);
    if (ZERO_MISSING) setPoint(target, name, 0);
}

function readFeedbackNumber(name, suffix, plcRaw, typedData) {
    const key = name.replace(/电功率$/, suffix);
    const plcValue = asNumber(plcRaw[key]);
    if (plcValue !== null) return plcValue;

    const typedValue = asNumber(typedData[key]);
    if (typedValue !== null) return typedValue;

    return null;
}

function readRunningState(name, plcRaw, switchData) {
    const key = name.replace(/电功率$/, "开关");
    const value = hasOwn(plcRaw, key) ? plcRaw[key] : switchData[key];

    if (value === true || value === 1 || value === "1" || value === "true") return true;
    if (value === false || value === 0 || value === "0" || value === "false") return false;

    return null;
}

function allocatePower(totalPower, names, plcRaw, frequencyData, switchData) {
    const frequencies = names.map(function (name) {
        const value = readFeedbackNumber(name, "频率", plcRaw, frequencyData);
        return value !== null && value > 0.1 ? value : 0;
    });

    const frequencySum = frequencies.reduce(function (sum, value) {
        return sum + value;
    }, 0);

    if (frequencySum > 0) {
        return names.map(function (_, index) {
            return totalPower * frequencies[index] / frequencySum;
        });
    }

    const runningStates = names.map(function (name) {
        return readRunningState(name, plcRaw, switchData);
    });
    const runningCount = runningStates.filter(function (state) {
        return state === true;
    }).length;

    if (runningCount > 0) {
        return runningStates.map(function (state) {
            return state === true ? totalPower / runningCount : 0;
        });
    }

    return names.map(function () {
        return totalPower / names.length;
    });
}

function setSplit(target, valueByDeviceId, missingDeviceIds, deviceId, names, plcRaw, frequencyData, switchData) {
    if (hasOwn(valueByDeviceId, deviceId)) {
        const values = allocatePower(valueByDeviceId[deviceId], names, plcRaw, frequencyData, switchData);
        for (let i = 0; i < names.length; i++) {
            setPoint(target, names[i], values[i]);
        }
        return;
    }
    missingDeviceIds.push(deviceId);
    if (ZERO_MISSING) {
        for (const name of names) setPoint(target, name, 0);
    }
}

function sumByPrefix(obj, prefix) {
    let total = 0;
    for (const key of Object.keys(obj)) {
        if (key.startsWith(prefix) && key.endsWith("电功率")) {
            const value = asNumber(obj[key]);
            if (value !== null) total += value;
        }
    }
    return total;
}

