function convertToThreeDimensionalArray(twoDimensionalArray) {
    const threeDimensionalArray = [];
    for (let i = 1; i < twoDimensionalArray.length; i++) {
        for (let j = 1; j < twoDimensionalArray[i].length; j++) {
            if (twoDimensionalArray[i][j] === "1") {
                threeDimensionalArray.push([i-1, j-1, 1]);
            }
        }
    }
    return threeDimensionalArray;
}

