function swapFirstAndSecondElements(listOfLists) {  
    return listOfLists.map(subList => {  
        if (subList.length >= 2) {  
            // 交换第一个元素和第二个元素  
            return [subList[1], subList[0]].concat(subList.slice(2));  
        } else {  
            // 如果子列表长度小于2，直接返回原列表  
            return subList;  
        }  
    });  
}  
