// Replace the "根据数组 查询冷冻水泵反馈频率" function with this version.
// It shows only running chilled-water pumps. If a running pump has no frequency
// feedback point in the PLC table, it is marked clearly instead of falling back
// to some other pump's frequency.

// If pumps without frequency feedback are fixed-speed pumps, change this to 50.
// Keep it as null when missing feedback should be shown as "无频率点".
const DEFAULT_FIXED_SPEED_HZ = null;

function asNumber(value) {
    const numberValue = Number(value);
    return Number.isFinite(numberValue) ? numberValue : null;
}

function isOn(value) {
    if (value === true || value === 1) return true;
    if (value === false || value === 0 || value === null || value === undefined) return false;

    const text = String(value).trim().toLowerCase();
    return text === "1" || text === "true" || text === "on" || text === "run" || text === "running" || text === "运行";
}

function uniqueSortedNumbers(values) {
    return Array.from(new Set(values.map(function (value) {
        return Number(value);
    }).filter(function (value) {
        return Number.isFinite(value);
    }))).sort(function (a, b) {
        return a - b;
    });
}

const plcRaw = global.get("PLC原始数据") || {};
const switchGlobal = global.get("开关") || {};
const frequencyGlobal = global.get("频率") || {};

const switchData = Object.assign({}, plcRaw, switchGlobal);
const frequencyData = Object.assign({}, plcRaw, frequencyGlobal);

let runningPumpNumbers = [];

for (const key of Object.keys(switchData)) {
    const match = key.match(/^反馈_冷冻水泵(\d+)开关$/);
    if (!match) continue;
    if (isOn(switchData[key])) runningPumpNumbers.push(match[1]);
}

// Keep the old upstream array as a fallback only when global.开关 is unavailable.
if (runningPumpNumbers.length === 0 && Array.isArray(msg.payload)) {
    runningPumpNumbers = msg.payload;
}

runningPumpNumbers = uniqueSortedNumbers(runningPumpNumbers);

const result = {};
