//提取对象内键为"字符串a"+数值+“字符串b”的元素
function extractObjectsWithPattern(obj, a, b) {
    const pattern = new RegExp(`^${a}\\d+${b}$`);

    return Object.keys(obj).reduce((acc, key) => {
        if (pattern.test(key)) {
            acc[key] = obj[key];
        }
        return acc;
    }, {});
}
//提取值为给定值的元素
function extractObjectsWithValue(obj, value) {
    return Object.keys(obj).reduce((acc, key) => {
        if (obj[key] === value) {
            acc[key] = obj[key];
        }
        return acc;
    }, {});
}


