//根据数组arr提取对象obj中的元素
function extractElements(arr, obj) {
    return arr.reduce((acc, key) => {
        if (key in obj) {
            acc[key] = obj[key];
        }
        return acc;
    }, {});
}
//使用数组 arr1 作为键，数组 arr2 作为值构建对象
