function removeStringFromKeys(obj, removeString) {
    const result = {};

    for (const key in obj) {
        if (obj.hasOwnProperty(key) && key.includes(removeString)) {
            const newKey = key.replace(removeString, '');
            result[newKey] = obj[key];
        } else {
            result[key] = obj[key];
        }
    }

    return result;
}

