//比较时间字符串的时分是否相同
function compareTime(time1, time2) {
    // 分割时间字符串为小时、分钟和秒
    const hour1 = time1.split(':')[0];
    const minute1 = time1.split(':')[1];
    const hour2 = time2.split(':')[0];
    const minute2 = time2.split(':')[1];


    // 转换为数值进行比较
    const time1Num = parseInt(hour1) * 60 + parseInt(minute1);
    const time2Num = parseInt(hour2) * 60 + parseInt(minute2);

    return time1Num === time2Num;
}

