// Shows only running chilled-water pumps. Pumps with no frequency feedback are marked.

const DEFAULT_FIXED_SPEED_HZ = null; // Change to 50 if no-feedback pumps are fixed-speed pumps.

function asNumber(value) {
    const numberValue = Number(value);
    return Number.isFinite(numberValue) ? numberValue : null;
}

function isOn(value) {
    if (value === true || value === 1) return true;
    if (value === false || value === 0 || value === null || value === undefined) return false;
    const text = String(value).trim().toLowerCase();
    return text === "1" || text === "true" || text === "on" || text === "run" || text === "running" || text === "运行";
}

function uniqueSortedNumbers(values) {
    return Array.from(new Set(values.map(Number).filter(Number.isFinite))).sort(function (a, b) {
        return a - b;
    });
}

const plcRaw = global.get("PLC原始数据") || {};
const switchData = Object.assign({}, plcRaw, global.get("开关") || {});
const frequencyData = Object.assign({}, plcRaw, global.get("频率") || {});

let runningPumpNumbers = Array.isArray(msg.payload) ? msg.payload : [];

if (runningPumpNumbers.length === 0) {
    for (const key of Object.keys(switchData)) {
        const match = key.match(/^反馈_冷冻水泵(\d+)开关$/);
        if (match && isOn(switchData[key])) runningPumpNumbers.push(match[1]);
    }
}

runningPumpNumbers = uniqueSortedNumbers(runningPumpNumbers);

const result = {};
const missing = [];

for (const pumpNo of runningPumpNumbers) {
    const key = "反馈_冷冻水泵" + pumpNo + "频率";
    const value = asNumber(frequencyData[key]);
    if (value === null) {
        if (DEFAULT_FIXED_SPEED_HZ === null) {
            result[String(pumpNo)] = "-";
            missing.push(pumpNo);
        } else {
            result[String(pumpNo)] = DEFAULT_FIXED_SPEED_HZ;
        }
    } else {
        result[String(pumpNo)] = Number(value.toFixed(1));
    }
}

if (missing.length > 0) {
    node.status({ fill: "yellow", shape: "dot", text: "缺少频率反馈:" + missing.join(",") });
} else {
    node.status({ fill: "green", shape: "dot", text: "反馈:" + JSON.stringify(result) });
}

msg.payload = result;
return msg;

