function getDateTimeDiffInMs(dateTimeStr) {
    const dateTime = new Date(dateTimeStr);
    const now = new Date();
    const diffInMs = now.getTime() - dateTime.getTime();  //毫秒比较
    return diffInMs;
}

const data = global.get('PLC实时数据') || {};
const dateTimeStr = data['DateTime'];   //2024/7/10 13:59:58

const diffInS = getDateTimeDiffInMs(dateTimeStr)/1000/60;

if (diffInS <= 1) { //1分钟
     msg.payload = true 
     global.set('PLCDataStatus', true);   //写入全局变量
} else if (diffInS > 1) { 
    msg.payload = false 
    global.set('PLCDataStatus', true);    //写入全局变量
}


//msg.payload = diffInS;
return msg;

