var ObjFirst = { 'DateTime': dateTime }
var ObjSecond = msg.payload;
var newObj = {};

Object.assign(newObj, ObjFirst, ObjSecond);

msg.payload = newObj
msg.topic = 'PLC实时数据'

global.set(msg.topic,msg.payload)
return msg;

function convertBooleanToNumber(obj) {
    for (let prop in obj) {
        if (typeof obj[prop] === 'boolean') {
            obj[prop] = obj[prop] ? 1 : 0;
        }
    }
